// Package blogger provides a client for the Blogger API v3.
package blogger

import (
	"context"
	"net/http"

	"google.golang.org/api/blogger/v3"
	"google.golang.org/api/option"
)

const defaultBaseServiceURL = "https://blogger.googleapis.com/"

// Client is a thin wrapper over the generated Blogger v3 service, exposing one
// accessor per API resource.
type Client struct {
	// Service is the underlying generated Blogger v3 service.
	Service *blogger.Service

	ctx context.Context

	httpClient *http.Client

	baseServiceURL string
}

// NewClient creates a Client using the supplied client options. When no HTTP
// client is supplied through opts, google.golang.org/api builds one from the
// default application credentials.
func NewClient(ctx context.Context, opts ...option.ClientOption) (*Client, error) {
	svc, err := blogger.NewService(ctx, opts...)
	if err != nil {
		return nil, err
	}

	return &Client{
		Service:        svc,
		ctx:            ctx,
		baseServiceURL: svc.BasePath,
	}, nil
}

// NewRawClient creates a Client backed by a caller-provided http.Client. It
// never fails and requires no credentials; use it when you manage
// authentication and transport yourself. The supplied client must not be nil.
func NewRawClient(httpClient *http.Client) *Client {
	return &Client{
		ctx:            context.Background(),
		httpClient:     httpClient,
		baseServiceURL: defaultBaseServiceURL,
	}
}

// WithContext returns a copy of the Client bound to ctx. The underlying Service
// and http.Client are shared, so nothing else about the Client changes.
func (c *Client) WithContext(ctx context.Context) *Client {
	clone := *c
	clone.ctx = ctx
	return &clone
}

// Blogs returns a builder for the blogs resource.
func (c *Client) Blogs() *blogger.BlogsService {
	return blogger.NewBlogsService(c.Service)
}

// Comments returns a builder for the comments resource.
func (c *Client) Comments() *blogger.CommentsService {
	return blogger.NewCommentsService(c.Service)
}

// Pages returns a builder for the pages resource.
func (c *Client) Pages() *blogger.PagesService {
	return blogger.NewPagesService(c.Service)
}

// Posts returns a builder for the posts resource.
func (c *Client) Posts() *blogger.PostsService {
	return blogger.NewPostsService(c.Service)
}

// Users returns a builder for the users resource.
func (c *Client) Users() *blogger.UsersService {
	return blogger.NewUsersService(c.Service)
}

// BlogUserInfos returns a builder for the blogUserInfos resource.
func (c *Client) BlogUserInfos() *blogger.BlogUserInfosService {
	return blogger.NewBlogUserInfosService(c.Service)
}

// PageViews returns a builder for the pageViews resource.
func (c *Client) PageViews() *blogger.PageViewsService {
	return blogger.NewPageViewsService(c.Service)
}

// PostUserInfos returns a builder for the postUserInfos resource.
func (c *Client) PostUserInfos() *blogger.PostUserInfosService {
	return blogger.NewPostUserInfosService(c.Service)
}

