	return fmt.Sprintf("v3/blogs/%s/posts/%s", url.PathEscape(blogId), url.PathEscape(postId))
}

func joinLabels(labels []string) string {
	builder := &strings.Builder{}

	written := false
	for _, label := range labels {
		if label == "" {
			continue
		}
		if written {
			builder.WriteByte(',')
		}
		builder.WriteString(label)
		written = true
	}

	return builder.String()
}

